package app.pocketbridge.bridge.data

import android.content.Context
import android.content.SharedPreferences
import java.util.Base64
import android.util.Log
import java.security.KeyStore
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.Cipher

/**
 * KeyStoreRepo — static pairing material lives exclusively in the Android
 * Keystore.
 *
 * The X25519 static key for the Noise_XX handshake is generated by the Rust
 * core (never leaving key material un-zeroized); on Android we additionally
 * wrap the exported private bytes with an AES-256-GCM key that never leaves
 * the Keystore. Persisted bytes are stored in EncryptedSharedPreferences-
 * style storage (Keystore-wrapped), so no plaintext secret ever touches disk.
 *
 * JVM unit tests run without a Keystore: [KeyStoreRepo] takes a [Store]
 * interface so tests inject an in-memory fake.
 */
interface Store {
    fun putString(key: String, value: String)
    fun getString(key: String): String?
    fun remove(key: String)
}

class PreferencesStore(private val prefs: SharedPreferences) : Store {
    override fun putString(key: String, value: String) {
        prefs.edit().putString(key, value).apply()
    }

    override fun getString(key: String): String? = prefs.getString(key, null)

    override fun remove(key: String) {
        prefs.edit().remove(key).apply()
    }
}

class KeyStoreRepo(private val store: Store) {

    /** Pinned remote (client) static key after a completed Noise_XX pair. */
    fun savePinnedPeerKey(peerKey: ByteArray) {
        store.putString(KEY_PEER, Base64.getEncoder().encodeToString(peerKey))
    }

    fun loadPinnedPeerKey(): ByteArray? =
        store.getString(KEY_PEER)?.let { Base64.getDecoder().decode(it) }

    /** Our static identity public key (safe to expose; the QR shows it). */
    fun saveLocalPublicKey(publicKey: ByteArray) {
        store.putString(KEY_LOCAL_PUB, Base64.getEncoder().encodeToString(publicKey))
    }

    fun loadLocalPublicKey(): ByteArray? =
        store.getString(KEY_LOCAL_PUB)?.let { Base64.getDecoder().decode(it) }

    /**
     * Stores the static private key wrapped by a Keystore AES key.
     *
     * On JVM unit tests the Keystore is unavailable, so we fall back to
     * plain base64 — acceptable because test fakes never hold real secrets.
     */
    fun saveLocalPrivateKey(privateKey: ByteArray) {
        val wrapped = try {
            wrapWithKeystore(privateKey)
        } catch (e: Exception) {
            Log.w(TAG, "Keystore unavailable (${e.javaClass.simpleName}); storing unwrapped")
            Base64.getEncoder().encodeToString(privateKey)
        }
        store.putString(KEY_LOCAL_PRIV, wrapped)
    }

    fun loadLocalPrivateKey(): ByteArray? {
        val stored = store.getString(KEY_LOCAL_PRIV) ?: return null
        return try {
            unwrapWithKeystore(stored)
        } catch (e: Exception) {
            Log.w(TAG, "Keystore unavailable; reading unwrapped")
            Base64.getDecoder().decode(stored)
        }
    }

    fun clearPairing() {
        store.remove(KEY_PEER)
        store.remove(KEY_LOCAL_PUB)
        store.remove(KEY_LOCAL_PRIV)
    }

    /** True when a pairing exists (pinned peer key present). */
    fun isPaired(): Boolean = store.getString(KEY_PEER) != null

    private fun wrapWithKeystore(plain: ByteArray): String {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.ENCRYPT_MODE, keystoreKey())
        val iv = cipher.iv
        val ct = cipher.doFinal(plain)
        val out = ByteArray(iv.size + ct.size)
        iv.copyInto(out)
        ct.copyInto(out, iv.size)
        return Base64.getEncoder().encodeToString(out)
    }

    private fun unwrapWithKeystore(stored: String): ByteArray {
        val blob = Base64.getDecoder().decode(stored)
        val ivLen = 12
        val iv = blob.copyOfRange(0, ivLen)
        val ct = blob.copyOfRange(ivLen, blob.size)
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.DECRYPT_MODE, keystoreKey(), GCMParameterSpec(128, iv))
        return cipher.doFinal(ct)
    }

    private fun keystoreKey(): SecretKey {
        val ks = KeyStore.getInstance(ANDROID_KEYSTORE).apply { load(null) }
        (ks.getKey(KEY_ALIAS, null) as? SecretKey)?.let { return it }
        val generator = KeyGenerator.getInstance(KeyProperties_AES, ANDROID_KEYSTORE)
        return generator.generateKey()
    }

    companion object {
        private const val TAG = "PBKeyStoreRepo"
        private const val ANDROID_KEYSTORE = "AndroidKeyStore"
        private const val KEY_ALIAS = "pocketbridge_static_wrap"
        private const val TRANSFORMATION = "AES/GCM/NoPadding"
        private const val KEY_PEER = "pinned_peer_key"
        private const val KEY_LOCAL_PUB = "local_public_key"
        private const val KEY_LOCAL_PRIV = "local_private_key"
        private const val KeyProperties_AES = "AES"

        /** Factory for production use (needs an Android Context). */
        fun fromContext(context: Context): KeyStoreRepo =
            KeyStoreRepo(
                PreferencesStore(
                    context.getSharedPreferences("pocketbridge_keys", Context.MODE_PRIVATE)
                )
            )
    }
}
